from __future__ import annotations

import importlib.util
import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path


SCRIPT = Path(__file__).with_name("normalize_aeneas_lean.py")
SPEC = importlib.util.spec_from_file_location("normalize_aeneas_lean", SCRIPT)
assert SPEC and SPEC.loader
NORMALIZER = importlib.util.module_from_spec(SPEC)
sys.modules[SPEC.name] = NORMALIZER
SPEC.loader.exec_module(NORMALIZER)


def raw(kind: str, body: str) -> str:
    return f"""\
-- THIS FILE WAS AUTOMATICALLY GENERATED BY AENEAS
-- [ark_ip_proofs]: {kind} definitions
import Aeneas
open Aeneas Aeneas.Std Result ControlFlow Error
set_option linter.dupNamespace false
set_option linter.hashCommand false
set_option linter.unusedVariables false
namespace ark_ip_proofs

{body.rstrip()}

end ark_ip_proofs
"""


class NormalizerTests(unittest.TestCase):
    def setUp(self) -> None:
        self.temp = tempfile.TemporaryDirectory(prefix="normalize-aeneas-test-")
        self.directory = Path(self.temp.name)

    def tearDown(self) -> None:
        self.temp.cleanup()

    def write(self, name: str, content: str) -> Path:
        path = self.directory / name
        path.write_text(content, encoding="utf-8")
        return path

    def run_normalize(
        self,
        inputs: list[Path],
        *,
        roots: tuple[str, ...] = (),
        extra: tuple[str, ...] = (),
        reuse: tuple[str, ...] = (),
    ):
        output = self.directory / "normalized.lean"
        command = [sys.executable, str(SCRIPT)]
        for path in inputs:
            command += ["--input", str(path)]
        command += ["--output", str(output), "--lean-root", str(self.directory)]
        for root in roots:
            command += ["--root", root]
        for module in extra:
            command += ["--extra-import", module]
        for module in reuse:
            command += ["--reuse-module", module]
        completed = subprocess.run(command, capture_output=True, text=True)
        return completed, output

    def test_rewrite_rules_extra_import_and_hash_metadata(self):
        source = self.write(
            "raw.lean",
            raw(
                "function",
                """\
@[irreducible, global_simps, simp]
def s3_07_arkworks_fq_spike.root (x : Std.U64) (y : Std.U128) (b : Std.U8) :
    Array Std.U64 4 := by
  let a : Array Std.U128 2 := Array.make 2
  let c : Array Std.U8 8 := Array.repeat b 8
  let z := UScalar.cast .U128 x
  let q := UScalar.cast UScalarTy.U64 y
  let u := UScalar.cast .U8 x
  let r := UScalar.cast .Usize x
  let _ := Array.index_usize a 0
  let _ := Array.update a 0 x
  let _ := Array.to_slice a
  let _ := Std.U64.ofNat 1
  let _ := Std.U128.ofNat 2
  #u64 3""",
            ),
        )
        completed, output = self.run_normalize(
            [source],
            roots=("ark_ip_proofs::s3_07_arkworks_fq_spike::root",),
            extra=("Ipp.Extracted.Foo",),
        )
        self.assertEqual(completed.returncode, 0, completed.stderr)
        result = output.read_text(encoding="utf-8")
        for spelling in (
            "import Ipp.Extracted.AeneasRuntime\nimport Ipp.Extracted.Foo",
            "@[irreducible, simp]",
            "MacCampaign.Array MacCampaign.U64 4",
            "MacCampaign.Array MacCampaign.U128 2",
            "MacCampaign.Array UInt8 8",
            "MacCampaign.Array.make 2",
            "MacCampaign.Array.replicate b 8",
            "MacCampaign.castU128 x",
            "MacCampaign.castU64 y",
            "MacCampaign.castU8 x",
            "MacCampaign.castUsize x",
            "MacCampaign.Array.index_usize",
            "MacCampaign.Array.update",
            "MacCampaign.Array.to_slice",
            "MacCampaign.U64.ofNat 1",
            "MacCampaign.U128.ofNat 2",
            "#u64 3",
        ):
            self.assertIn(spelling, result)
        metadata = json.loads(completed.stdout)
        self.assertEqual(len(metadata["selected_raw_declarations_sha256"]), 64)
        self.assertNotIn("raw_sha256", metadata)
        self.assertEqual(len(metadata["normalized_sha256"]), 64)
        self.assertEqual(
            NORMALIZER.NORMALIZED_ARTIFACT_REVISION,
            "normalize-aeneas-lean-v7",
        )
        self.assertEqual(
            result.splitlines()[1],
            "-- Deterministically assembled by normalize-aeneas-lean-v7.",
        )
        self.assertEqual(
            metadata["normalizer_revision"],
            "normalize-aeneas-lean-v8",
        )
        self.assertFalse(output.with_name(output.name + ".provenance.json").exists())

    def test_strips_trailing_horizontal_whitespace(self):
        source = self.write(
            "raw.lean",
            raw(
                "function",
                "def spike.helper : Nat := 1   \n"
                "def spike.root : Nat := spike.helper\t",
            ),
        )
        completed, output = self.run_normalize(
            [source],
            roots=("ark_ip_proofs::spike::root",),
        )
        self.assertEqual(completed.returncode, 0, completed.stderr)
        result = output.read_text(encoding="utf-8")
        self.assertFalse(
            any(line.endswith((" ", "\t")) for line in result.splitlines())
        )

